from pathlib import Path
import hashlib,json,collections
p=Path('/scratch/alpine/paco0228/ACE/results/ace_llm_intervention_screen_prompt_cpu_20261108_01/cpu01/worker/artifacts/tokenization.json')
raw=p.read_bytes();pin=hashlib.sha256(raw).hexdigest()
assert pin=='fb663a035eef20420fe461bc4dfa4fa6afa8462b38e32e1262c5661f666ff72c'
rows=json.loads(raw)['rows'];commands={}
for r in rows:
 for c,ids in r['commands'].items():
  if c in commands:assert commands[c]['ids']==ids
  else:commands[c]={'ids':ids,'length_with_eos':len(ids),'occurrences':0}
  commands[c]['occurrences']+=1
print(json.dumps({'tokenization_sha256':pin,'commands':commands,'longest_prompts':[{'fixture_id':r['fixture_id'],'prompt_tokens':len(r['prompt_ids']),'command_count':len(r['commands'])} for r in sorted(rows,key=lambda r:len(r['prompt_ids']),reverse=True)[:4]]},sort_keys=True))
